import os, pty, fcntl, termios, struct, time, select, sys, re

ROWS, COLS = 24, 80

def set_winsize(fd, rows, cols):
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))

class Screen:
    def __init__(self, rows=ROWS, cols=COLS):
        self.rows=rows; self.cols=cols
        self.buf=[[' ']*cols for _ in range(rows)]
        self.r=0; self.c=0
    def ensure(self):
        self.r=max(0,min(self.rows-1,self.r)); self.c=max(0,min(self.cols-1,self.c))
    def put(self,ch):
        if 0<=self.r<self.rows and 0<=self.c<self.cols:
            self.buf[self.r][self.c]=ch
        if self.c<self.cols-1:
            self.c+=1
    def write_text(self,text):
        for ch in text:
            if ch=='\r':
                self.c=0
            elif ch=='\n':
                if self.r<self.rows-1:
                    self.r+=1
            elif ch=='\b':
                if self.c>0: self.c-=1
            elif ch>= ' ':
                self.put(ch)
    def csi(self, params, final):
        p=[int(x) if x else 0 for x in params.split(';')] if params else [0]
        if final=='A': self.r-= p[0] or 1
        elif final=='B': self.r+= p[0] or 1
        elif final=='C': self.c+= p[0] or 1
        elif final=='D': self.c-= p[0] or 1
        elif final in ('H','f'):
            row=(p[0] or 1)-1
            col=(p[1] or 1)-1 if len(p)>1 else 0
            self.r=row; self.c=col
        elif final=='J':
            n=p[0]
            if n==2:
                self.buf=[[' ']*self.cols for _ in range(self.rows)]
                self.r=self.c=0
            elif n==0:
                for rr in range(self.r,self.rows):
                    start=self.c if rr==self.r else 0
                    for cc in range(start,self.cols): self.buf[rr][cc]=' '
        elif final=='K':
            n=p[0]
            if n in (0,2):
                start=0 if n==2 else self.c
                for cc in range(start,self.cols): self.buf[self.r][cc]=' '
        # ignore m,t,h,l,n
        self.ensure()
    def dump(self):
        return '\n'.join(''.join(r).rstrip() for r in self.buf[:12])

