package main

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"math"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"syscall"
	"time"
	"unicode/utf8"

	"github.com/mattn/go-runewidth"
	"golang.org/x/sys/unix"
	"golang.org/x/term"
)

const (
	version              = "v1.13.0"
	headerColor          = 59
	queryColor           = 70
	defaultMainColor     = 99
	deleteColor          = 196
	foregroundColor      = 231
	keyReadDelay         = 10 * time.Millisecond
	deleteCountdown      = 5 * time.Second
	terminalQuery        = "\x1b]11;?\x1b\\\x1b[6n"
	enterAltScreen       = "\x1b[?1049h\x1b[2J\x1b[H"
	leaveAltScreen       = "\x1b[?1049l"
	hideCursor           = "\x1b[?25l"
	showCursor           = "\x1b[?25h"
	enableBracketedPaste = "\x1b[?2004h"
	disableModes         = "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l"
)

var cliHelp = strings.TrimLeft(`
  walk v1.13.0

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode
`, "\n")

var uiHelpLines = []string{
	"",
	"    arrows, hjkl  Move cursor",
	"    enter         Enter directory",
	"    backspace     Exit directory",
	"    space         Toggle preview",
	"    esc, q        Exit with cd",
	"    ctrl+c        Exit without cd",
	"    /             Fuzzy search",
	"    d, delete     Delete file or dir",
	"    y             Copy to clipboard",
	"    .             Hide hidden files",
	"    ?             Show help",
	"",
	"",
}

type config struct {
	icons      bool
	dirOnly    bool
	hideHidden bool
	preview    bool
	withBorder bool
	fuzzy      bool
}

type cliMode int

const (
	modeRun cliMode = iota
	modeHelp
	modeVersion
)

type entry struct {
	name     string
	fullPath string
	dirEntry os.DirEntry
}

func (e entry) IsDir() bool {
	return e.dirEntry != nil && e.dirEntry.IsDir()
}

func (e entry) displayName(withIcons bool, matcher *iconMatcher) string {
	name := e.name
	if e.IsDir() {
		name += "/"
	}
	if !withIcons || matcher == nil {
		return name
	}
	icon := matcher.iconFor(e.dirEntry, e.fullPath)
	if icon == "" {
		return name
	}
	return icon + " " + name
}

type pendingDelete struct {
	name         string
	originalPath string
	temporary    string
	canUndo      bool
	deadline     time.Time
}

type keyKind int

const (
	keyUnknown keyKind = iota
	keyRune
	keyEnter
	keyBackspace
	keyEsc
	keyCtrlC
	keyUp
	keyDown
	keyLeft
	keyRight
	keyShiftUp
	keyShiftDown
	keyDelete
)

type keyEvent struct {
	kind keyKind
	r    rune
}

type selectionMode int

const (
	selectFirst selectionMode = iota
	selectKeepIndex
	selectByName
)

type selectionSpec struct {
	mode  selectionMode
	index int
	name  string
}

type app struct {
	tty          *os.File
	fd           int
	rawState     *term.State
	cfg          config
	mainColor    int
	openWith     map[string]string
	removeCmd    string
	status       *statusProgram
	icons        *iconMatcher
	currentPath  string
	entries      []entry
	selected     int
	scroll       int
	searchMode   bool
	searchQuery  string
	showHelp     bool
	topMessage   string
	currentError error
	preview      bool
	lastLines    int
	rows         int
	cols         int
	armedDelete  int
	pending      *pendingDelete
}

func main() {
	cfg, path, mode := parseArgs(os.Args[1:])
	switch mode {
	case modeHelp:
		fmt.Fprintln(os.Stdout, cliHelp)
		os.Exit(1)
	case modeVersion:
		fmt.Fprintln(os.Stdout, version)
		return
	}

	status := compileStatusProgram(os.Getenv("WALK_STATUS_BAR"))
	icons := (*iconMatcher)(nil)
	if cfg.icons {
		icons = mustLoadIconMatcher()
	}

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		panic(fmt.Errorf("could not open a new TTY: %w", err))
	}
	defer tty.Close()

	if path == "" {
		cwd, cwdErr := os.Getwd()
		if cwdErr != nil {
			panic(cwdErr)
		}
		path = cwd
	}

	a := &app{
		tty:         tty,
		fd:          int(tty.Fd()),
		cfg:         cfg,
		mainColor:   parseMainColor(os.Getenv("WALK_MAIN_COLOR")),
		openWith:    parseOpenWith(os.Getenv("WALK_OPEN_WITH")),
		removeCmd:   os.Getenv("WALK_REMOVE_CMD"),
		status:      status,
		icons:       icons,
		currentPath: path,
		selected:    -1,
		armedDelete: -1,
		preview:     cfg.preview,
		searchMode:  cfg.fuzzy,
	}
	a.refreshSize()
	a.reload(selectionSpec{mode: selectFirst})
	if err := a.run(); err != nil {
		panic(err)
	}
}

func parseArgs(args []string) (config, string, cliMode) {
	var cfg config
	var path string
	for _, arg := range args {
		switch arg {
		case "--help", "-h":
			return cfg, path, modeHelp
		case "--version":
			return cfg, path, modeVersion
		case "--icons":
			cfg.icons = true
		case "--dir-only":
			cfg.dirOnly = true
		case "--hide-hidden":
			cfg.hideHidden = true
		case "--preview":
			cfg.preview = true
		case "--with-border":
			cfg.withBorder = true
		case "--fuzzy":
			cfg.fuzzy = true
		default:
			if path == "" {
				path = arg
			}
		}
	}
	return cfg, path, modeRun
}

func parseMainColor(raw string) int {
	if raw == "" {
		return defaultMainColor
	}
	n, err := strconv.Atoi(raw)
	if err != nil {
		return -1
	}
	return n
}

func parseOpenWith(raw string) map[string]string {
	result := map[string]string{}
	if strings.TrimSpace(raw) == "" {
		return result
	}
	for _, part := range strings.Split(raw, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		key, value, ok := strings.Cut(part, ":")
		if !ok {
			continue
		}
		key = strings.TrimPrefix(strings.ToLower(strings.TrimSpace(key)), ".")
		value = strings.TrimSpace(value)
		if key == "" || value == "" {
			continue
		}
		result[key] = value
	}
	return result
}

func (a *app) run() error {
	if err := a.enterTerminal(); err != nil {
		return err
	}
	defer func() {
		_ = a.restoreRaw()
	}()

	sigwinch := make(chan os.Signal, 1)
	signal.Notify(sigwinch, syscall.SIGWINCH)
	defer signal.Stop(sigwinch)

	input := make(chan keyEvent, 8)
	errs := make(chan error, 1)
	go a.readInput(input, errs)

	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()

	a.render()

	for {
		select {
		case err := <-errs:
			if err != nil && !errors.Is(err, io.EOF) {
				return err
			}
			return nil
		case <-sigwinch:
			a.refreshSize()
			a.render()
		case <-ticker.C:
			if a.tick(time.Now()) {
				a.render()
			}
		case key := <-input:
			if a.handleKey(key) {
				return nil
			}
			a.render()
		}
	}
}

func (a *app) readInput(out chan<- keyEvent, errs chan<- error) {
	reader := bufio.NewReader(a.tty)
	for {
		b, err := reader.ReadByte()
		if err != nil {
			errs <- err
			return
		}
		seq := []byte{b}
		if b == 0x1b {
			time.Sleep(keyReadDelay)
			for {
				available, ioctlErr := unix.IoctlGetInt(a.fd, unix.FIONREAD)
				if ioctlErr != nil || available <= 0 {
					break
				}
				buf := make([]byte, available)
				n, readErr := a.tty.Read(buf)
				if n > 0 {
					seq = append(seq, buf[:n]...)
				}
				if readErr != nil {
					break
				}
				time.Sleep(1 * time.Millisecond)
			}
		}
		out <- parseKey(seq)
	}
}

func parseKey(seq []byte) keyEvent {
	if len(seq) == 0 {
		return keyEvent{kind: keyUnknown}
	}
	if len(seq) == 1 {
		switch seq[0] {
		case 0x03:
			return keyEvent{kind: keyCtrlC}
		case '\r', '\n':
			return keyEvent{kind: keyEnter}
		case 0x7f, 0x08:
			return keyEvent{kind: keyBackspace}
		case 0x1b:
			return keyEvent{kind: keyEsc}
		default:
			if seq[0] < utf8.RuneSelf {
				return keyEvent{kind: keyRune, r: rune(seq[0])}
			}
		}
	}

	s := string(seq)
	switch s {
	case "\x1b[A":
		return keyEvent{kind: keyUp}
	case "\x1b[B":
		return keyEvent{kind: keyDown}
	case "\x1b[C":
		return keyEvent{kind: keyRight}
	case "\x1b[D":
		return keyEvent{kind: keyLeft}
	case "\x1b[1;2A":
		return keyEvent{kind: keyShiftUp}
	case "\x1b[1;2B":
		return keyEvent{kind: keyShiftDown}
	case "\x1b[3~":
		return keyEvent{kind: keyDelete}
	}
	if strings.HasPrefix(s, "\x1b]") || strings.HasSuffix(s, "R") {
		return keyEvent{kind: keyUnknown}
	}
	if len(seq) == 1 {
		return keyEvent{kind: keyRune, r: rune(seq[0])}
	}
	r, _ := utf8.DecodeRune(seq)
	if r != utf8.RuneError {
		return keyEvent{kind: keyRune, r: r}
	}
	return keyEvent{kind: keyUnknown}
}

func (a *app) enterTerminal() error {
	if _, err := io.WriteString(a.tty, terminalQuery); err != nil {
		return err
	}
	state, err := term.MakeRaw(a.fd)
	if err != nil {
		return err
	}
	a.rawState = state
	if a.preview {
		if _, err := io.WriteString(a.tty, hideCursor+enterAltScreen+hideCursor+enableBracketedPaste); err != nil {
			return err
		}
		return nil
	}
	_, err = io.WriteString(a.tty, hideCursor+enableBracketedPaste)
	return err
}

func (a *app) restoreRaw() error {
	if a.rawState == nil {
		return nil
	}
	err := term.Restore(a.fd, a.rawState)
	a.rawState = nil
	return err
}

func (a *app) refreshSize() {
	cols, rows, err := term.GetSize(a.fd)
	if err != nil || cols <= 0 || rows <= 0 {
		a.cols, a.rows = 80, 24
		return
	}
	a.cols, a.rows = cols, rows
}

func (a *app) handleKey(key keyEvent) bool {
	if a.showHelp {
		a.showHelp = false
		if key.kind == keyUnknown {
			return false
		}
	}

	switch key.kind {
	case keyUnknown:
		return false
	case keyCtrlC:
		a.exit(false)
		os.Exit(2)
	case keyEsc:
		a.exit(true)
		return true
	case keyRune:
		return a.handleRune(key.r)
	case keyEnter:
		a.clearTopMessage()
		a.clearDeleteArm()
		a.searchMode = false
		a.searchQuery = ""
		a.activateSelection()
	case keyBackspace:
		a.clearTopMessage()
		if a.searchMode {
			a.handleSearchBackspace()
			return false
		}
		a.clearDeleteArm()
		a.goUp()
	case keyUp:
		a.clearTopMessage()
		a.clearDeleteArm()
		a.moveSelection(-1)
	case keyDown:
		a.clearTopMessage()
		a.clearDeleteArm()
		a.moveSelection(1)
	case keyShiftUp:
		a.clearTopMessage()
		a.clearDeleteArm()
		a.jumpSelection(0)
	case keyShiftDown:
		a.clearTopMessage()
		a.clearDeleteArm()
		a.jumpSelection(len(a.entries) - 1)
	case keyLeft:
		a.clearTopMessage()
		a.clearDeleteArm()
		a.goUp()
	case keyRight:
		a.clearTopMessage()
		a.clearDeleteArm()
		a.searchMode = false
		a.searchQuery = ""
		a.activateSelection()
	case keyDelete:
		a.clearTopMessage()
		a.armOrDelete()
	}
	return false
}

func (a *app) handleRune(r rune) bool {
	switch r {
	case 'q':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.exit(true)
		return true
	case 'j':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.moveSelection(1)
	case 'k':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.moveSelection(-1)
	case 'h':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.goUp()
	case 'l':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.activateSelection()
	case '/':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.searchMode = true
		a.searchQuery = ""
	case 'd':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.armOrDelete()
	case 'u':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.undoDelete()
	case 'y':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.copySelection()
	case '.':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		oldIndex := a.selected
		a.cfg.hideHidden = !a.cfg.hideHidden
		a.reload(selectionSpec{mode: selectKeepIndex, index: oldIndex})
	case '?':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.showHelp = true
	case ' ':
		if a.searchMode {
			a.appendSearchRune(r)
			return false
		}
		a.clearTopMessage()
		a.clearDeleteArm()
		a.togglePreview()
	default:
		if a.searchMode {
			a.appendSearchRune(r)
		}
	}
	return false
}

func (a *app) handleSearchBackspace() {
	a.clearDeleteArm()
	if a.searchQuery == "" {
		a.searchMode = false
		return
	}
	runes := []rune(a.searchQuery)
	a.searchQuery = string(runes[:len(runes)-1])
	if a.searchQuery != "" {
		a.jumpToBestMatch()
	}
}

func (a *app) appendSearchRune(r rune) {
	a.clearDeleteArm()
	a.searchMode = true
	a.searchQuery += string(r)
	a.jumpToBestMatch()
}

func (a *app) moveSelection(delta int) {
	if len(a.entries) == 0 || a.selected < 0 {
		return
	}
	next := a.selected + delta
	if next < 0 {
		next = len(a.entries) - 1
	}
	if next >= len(a.entries) {
		next = 0
	}
	a.selected = next
	a.ensureVisible()
}

func (a *app) jumpSelection(index int) {
	if len(a.entries) == 0 {
		return
	}
	if index < 0 {
		index = 0
	}
	if index >= len(a.entries) {
		index = len(a.entries) - 1
	}
	a.selected = index
	a.ensureVisible()
}

func (a *app) jumpToBestMatch() {
	if a.searchQuery == "" || len(a.entries) == 0 {
		return
	}
	bestIndex := -1
	bestScore := math.MinInt
	for idx, item := range a.entries {
		score, ok := fuzzyScore(item.name, a.searchQuery)
		if !ok {
			continue
		}
		if score > bestScore || (score == bestScore && idx > bestIndex) {
			bestScore = score
			bestIndex = idx
		}
	}
	if bestIndex >= 0 {
		a.selected = bestIndex
		a.ensureVisible()
	}
}

func fuzzyScore(name, query string) (int, bool) {
	nameRunes := []rune(strings.ToLower(name))
	queryRunes := []rune(strings.ToLower(query))
	if len(queryRunes) == 0 {
		return 0, false
	}

	first, last := -1, -1
	pos := 0
	for _, q := range queryRunes {
		found := false
		for pos < len(nameRunes) {
			if nameRunes[pos] == q {
				if first == -1 {
					first = pos
				}
				last = pos
				pos++
				found = true
				break
			}
			pos++
		}
		if !found {
			return 0, false
		}
	}

	score := 1000 - (last - first)
	if strings.HasPrefix(strings.ToLower(name), strings.ToLower(query)) {
		score += 2000
	}
	if idx := strings.Index(strings.ToLower(name), strings.ToLower(query)); idx >= 0 {
		score += 1000 - idx
	}
	score -= len(nameRunes) - len(queryRunes)
	return score, true
}

func (a *app) currentEntry() *entry {
	if a.selected < 0 || a.selected >= len(a.entries) {
		return nil
	}
	return &a.entries[a.selected]
}

func (a *app) reload(spec selectionSpec) {
	dirEntries, err := os.ReadDir(a.currentPath)
	if err != nil {
		a.entries = nil
		a.currentError = err
		a.selected = -1
		a.scroll = 0
		return
	}

	items := make([]entry, 0, len(dirEntries))
	for _, de := range dirEntries {
		name := de.Name()
		if a.cfg.hideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if a.cfg.dirOnly && !de.IsDir() {
			continue
		}
		items = append(items, entry{
			name:     name,
			fullPath: filepath.Join(a.currentPath, name),
			dirEntry: de,
		})
	}

	sort.Slice(items, func(i, j int) bool {
		return items[i].name < items[j].name
	})

	a.entries = items
	a.currentError = nil

	if len(items) == 0 {
		a.selected = -1
		a.scroll = 0
		return
	}

	switch spec.mode {
	case selectKeepIndex:
		if spec.index < 0 {
			a.selected = 0
		} else if spec.index >= len(items) {
			a.selected = len(items) - 1
		} else {
			a.selected = spec.index
		}
	case selectByName:
		a.selected = 0
		for idx, item := range items {
			if item.name == spec.name {
				a.selected = idx
				break
			}
		}
	default:
		a.selected = 0
	}
	a.ensureVisible()
}

func (a *app) ensureVisible() {
	visibleRows := a.listRowsAvailable()
	if visibleRows <= 0 || a.selected < 0 {
		a.scroll = 0
		return
	}
	if a.selected < a.scroll {
		a.scroll = a.selected
	}
	if a.selected >= a.scroll+visibleRows {
		a.scroll = a.selected - visibleRows + 1
	}
	if a.scroll < 0 {
		a.scroll = 0
	}
}

func (a *app) activateSelection() {
	item := a.currentEntry()
	if item == nil {
		return
	}
	if item.IsDir() {
		a.currentPath = item.fullPath
		a.selected = -1
		a.scroll = 0
		a.reload(selectionSpec{mode: selectFirst})
		return
	}
	_ = a.openEntry(*item)
}

func (a *app) goUp() {
	parent := filepath.Dir(a.currentPath)
	if parent == a.currentPath {
		return
	}
	child := filepath.Base(a.currentPath)
	a.currentPath = parent
	a.reload(selectionSpec{mode: selectByName, name: child})
}

func (a *app) armOrDelete() {
	if a.currentEntry() == nil {
		return
	}
	if a.armedDelete == a.selected {
		a.performDelete()
		return
	}
	a.armedDelete = a.selected
}

func (a *app) clearDeleteArm() {
	a.armedDelete = -1
}

func (a *app) performDelete() {
	item := a.currentEntry()
	if item == nil {
		return
	}
	oldIndex := a.selected
	a.armedDelete = -1

	pending := &pendingDelete{
		name:         item.name,
		originalPath: item.fullPath,
		deadline:     time.Now().Add(deleteCountdown),
	}

	if strings.TrimSpace(a.removeCmd) != "" {
		_ = runShellCommand(a.removeCmd, item.fullPath, os.Stdin, os.Stdout, os.Stderr)
	} else {
		temporary, err := moveToTrash(item.fullPath)
		if err != nil {
			a.topMessage = err.Error()
			return
		}
		pending.temporary = temporary
		pending.canUndo = true
	}

	a.pending = pending
	a.reload(selectionSpec{mode: selectKeepIndex, index: oldIndex})
}

func moveToTrash(path string) (string, error) {
	base := filepath.Base(path)
	trashDir, err := os.MkdirTemp("", "walk-trash-")
	if err != nil {
		return "", err
	}
	target := filepath.Join(trashDir, base)
	if err := os.Rename(path, target); err != nil {
		_ = os.RemoveAll(trashDir)
		return "", err
	}
	return target, nil
}

func (a *app) undoDelete() {
	if a.pending == nil {
		return
	}
	defer func() {
		if !a.pending.canUndo {
			a.pending = nil
		}
	}()

	if !a.pending.canUndo || a.pending.temporary == "" {
		return
	}
	if err := os.Rename(a.pending.temporary, a.pending.originalPath); err != nil {
		return
	}
	_ = os.Remove(filepath.Dir(a.pending.temporary))
	restoredDir := filepath.Dir(a.pending.originalPath)
	name := filepath.Base(a.pending.originalPath)
	a.pending = nil
	if a.currentPath == restoredDir {
		a.reload(selectionSpec{mode: selectByName, name: name})
	}
}

func (a *app) tick(now time.Time) bool {
	if a.pending == nil {
		return false
	}
	if now.Before(a.pending.deadline) {
		return true
	}
	if a.pending.canUndo && a.pending.temporary != "" {
		_ = os.RemoveAll(filepath.Dir(a.pending.temporary))
	}
	a.pending = nil
	return true
}

func (a *app) copySelection() {
	item := a.currentEntry()
	if item == nil {
		return
	}
	_ = copyToClipboard(item.fullPath)
	a.topMessage = "copied: " + item.fullPath
}

func copyToClipboard(value string) error {
	type clipboardCmd struct {
		name string
		args []string
	}
	commands := []clipboardCmd{
		{name: "wl-copy"},
		{name: "xclip", args: []string{"-selection", "clipboard"}},
		{name: "xsel", args: []string{"--clipboard", "--input"}},
		{name: "pbcopy"},
		{name: "clip.exe"},
	}
	for _, candidate := range commands {
		if _, err := exec.LookPath(candidate.name); err != nil {
			continue
		}
		cmd := exec.Command(candidate.name, candidate.args...)
		cmd.Stdin = strings.NewReader(value)
		if err := cmd.Run(); err == nil {
			return nil
		}
	}
	return nil
}

func (a *app) togglePreview() {
	a.preview = !a.preview
	if a.preview {
		_, _ = io.WriteString(a.tty, enterAltScreen+hideCursor)
	} else {
		_, _ = io.WriteString(a.tty, leaveAltScreen+hideCursor)
	}
}

func (a *app) openEntry(item entry) error {
	cmd := a.commandForEntry(item)
	if cmd == nil {
		return nil
	}
	return a.runExternal(cmd)
}

func (a *app) commandForEntry(item entry) *exec.Cmd {
	ext := strings.TrimPrefix(strings.ToLower(filepath.Ext(item.name)), ".")
	if openCmd, ok := a.openWith[ext]; ok {
		return shellCommand(openCmd, item.fullPath)
	}
	if editor := os.Getenv("WALK_EDITOR"); editor != "" {
		return shellCommand(editor, item.fullPath)
	}
	if editor := os.Getenv("EDITOR"); editor != "" {
		return shellCommand(editor, item.fullPath)
	}
	if _, err := exec.LookPath("less"); err == nil {
		return exec.Command("less", item.fullPath)
	}
	return exec.Command("cat", item.fullPath)
}

func shellCommand(command, path string) *exec.Cmd {
	return exec.Command("sh", "-c", command+" \"$1\"", "sh", path)
}

func runShellCommand(command, path string, stdin io.Reader, stdout, stderr io.Writer) error {
	cmd := shellCommand(command, path)
	cmd.Stdin = stdin
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	return cmd.Run()
}

func (a *app) runExternal(cmd *exec.Cmd) error {
	if err := a.suspendForCommand(); err != nil {
		return err
	}
	defer func() {
		_ = a.resumeAfterCommand()
	}()
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func (a *app) suspendForCommand() error {
	if err := a.restoreRaw(); err != nil {
		return err
	}
	if a.preview {
		if _, err := io.WriteString(a.tty, disableModes+leaveAltScreen); err != nil {
			return err
		}
		return nil
	}
	_, err := io.WriteString(a.tty, "\r\x1b[2K"+disableModes)
	return err
}

func (a *app) resumeAfterCommand() error {
	state, err := term.MakeRaw(a.fd)
	if err != nil {
		return err
	}
	a.rawState = state
	if a.preview {
		if _, err := io.WriteString(a.tty, enterAltScreen+hideCursor+enableBracketedPaste); err != nil {
			return err
		}
	} else {
		if _, err := io.WriteString(a.tty, hideCursor+enableBracketedPaste); err != nil {
			return err
		}
	}
	a.render()
	return nil
}

func (a *app) exit(printPath bool) {
	if a.preview {
		_, _ = io.WriteString(a.tty, leaveAltScreen)
	} else {
		a.clearNormalRender()
	}
	_ = a.restoreRaw()
	_, _ = io.WriteString(a.tty, disableModes)
	if printPath {
		fmt.Fprintln(os.Stdout, a.currentPath)
	}
}

func (a *app) clearNormalRender() {
	if a.lastLines <= 0 {
		return
	}
	var b strings.Builder
	b.WriteString(fmt.Sprintf("\x1b[%dA", a.lastLines-1))
	for i := 0; i < a.lastLines; i++ {
		b.WriteString("\r\x1b[2K")
		if i+1 < a.lastLines {
			b.WriteString("\n")
		}
	}
	b.WriteString("\r")
	_, _ = io.WriteString(a.tty, b.String())
	a.lastLines = 0
}

func (a *app) clearTopMessage() {
	a.topMessage = ""
}

func (a *app) render() {
	lines := a.buildLines()
	if a.preview {
		a.renderPreview(lines)
		return
	}
	a.renderNormal(lines)
}

func (a *app) renderPreview(lines []string) {
	var b strings.Builder
	b.WriteString("\x1b[H")
	for i, line := range lines {
		b.WriteString("\r")
		b.WriteString(line)
		b.WriteString("\x1b[K")
		if i+1 < len(lines) {
			b.WriteString("\n")
		}
	}
	b.WriteString("\x1b[J")
	_, _ = io.WriteString(a.tty, b.String())
	a.lastLines = len(lines)
}

func (a *app) renderNormal(lines []string) {
	var b strings.Builder
	if a.lastLines > 0 {
		b.WriteString(fmt.Sprintf("\x1b[%dA", a.lastLines-1))
	}
	maxLines := len(lines)
	if a.lastLines > maxLines {
		maxLines = a.lastLines
	}
	for i := 0; i < maxLines; i++ {
		b.WriteString("\r")
		if i < len(lines) {
			b.WriteString(lines[i])
		}
		b.WriteString("\x1b[K")
		if i+1 < maxLines {
			b.WriteString("\n")
		}
	}
	b.WriteString("\r")
	_, _ = io.WriteString(a.tty, b.String())
	a.lastLines = len(lines)
}

func (a *app) buildLines() []string {
	if a.showHelp {
		lines := []string{styleBar("help")}
		lines = append(lines, uiHelpLines...)
		return lines
	}
	if a.preview {
		return a.buildPreviewLines()
	}
	return a.buildNormalLines()
}

func (a *app) buildNormalLines() []string {
	lines := []string{a.headerLine(a.headerText(), a.searchSuffix(), a.cols)}
	bodyRows := a.rows - 1
	footer := a.footerLine()
	if footer != "" {
		bodyRows--
	}
	lines = append(lines, a.normalBodyLines(bodyRows)...)
	if footer != "" {
		lines = append(lines, styleBar(footer))
	}
	return lines
}

func (a *app) normalBodyLines(limit int) []string {
	if limit <= 0 {
		return nil
	}
	if a.currentError != nil {
		return popupLines(a.currentError.Error(), limit)
	}
	if len(a.entries) == 0 {
		return popupLines("No files", limit)
	}
	return a.renderList(limit, 0)
}

func (a *app) buildPreviewLines() []string {
	footer := a.footerLine()
	contentRows := a.rows - 1
	if footer != "" {
		contentRows--
	}
	leftWidth, rightWidth := splitPreviewWidth(a.cols, a.cfg.withBorder)
	lines := []string{
		a.previewHeaderLine(leftWidth, rightWidth),
	}

	leftLines := a.previewLeftLines(contentRows, leftWidth)
	rightLines := a.previewRightLines(contentRows, rightWidth)
	for i := 0; i < contentRows; i++ {
		left := ""
		right := ""
		if i < len(leftLines) {
			left = leftLines[i]
		}
		if i < len(rightLines) {
			right = rightLines[i]
		}
		lines = append(lines, joinPreviewLine(left, right, leftWidth, rightWidth, a.cfg.withBorder, a.mainColor))
	}
	if footer != "" {
		lines = append(lines, styleBar(footer))
	}
	return lines
}

func splitPreviewWidth(cols int, withBorder bool) (int, int) {
	gap := 2
	if withBorder {
		gap = 3
	}
	left := (cols - gap) / 2
	if left < 1 {
		left = 1
	}
	right := cols - gap - left
	if right < 0 {
		right = 0
	}
	return left, right
}

func joinPreviewLine(left, right string, leftWidth, rightWidth int, withBorder bool, color int) string {
	left = truncatePad(left, leftWidth)
	right = truncatePad(right, rightWidth)
	if withBorder {
		return left + " " + fgColor("|", color) + " " + right
	}
	return left + "  " + right
}

func (a *app) previewHeaderLine(leftWidth, rightWidth int) string {
	left := styleBar(truncatePad(a.headerText(), leftWidth))
	rightText := ""
	if item := a.currentEntry(); item != nil {
		rightText = item.name
	}
	right := styleBar(truncatePad(rightText, rightWidth))
	if a.cfg.withBorder {
		return left + " " + fgColor("|", a.mainColor) + " " + right
	}
	return left + "  " + right
}

func (a *app) previewLeftLines(limit, width int) []string {
	if limit <= 0 {
		return nil
	}
	if a.currentError != nil {
		return padAll(popupLines(a.currentError.Error(), limit), width)
	}
	if len(a.entries) == 0 {
		return padAll(popupLines("No files", limit), width)
	}
	return padAll(a.renderList(limit, width), width)
}

func (a *app) previewRightLines(limit, width int) []string {
	if limit <= 0 || width <= 0 {
		return nil
	}
	item := a.currentEntry()
	if item == nil {
		return nil
	}
	if item.IsDir() {
		items, err := a.readPreviewDir(item.fullPath)
		if err != nil {
			return popupLines(err.Error(), limit)
		}
		if len(items) == 0 {
			return popupLines("No files", limit)
		}
		lines := make([]string, 0, limit)
		for _, name := range items {
			if len(lines) >= limit {
				break
			}
			lines = append(lines, truncatePad(name, width))
		}
		return lines
	}
	return a.readPreviewFile(item.fullPath, limit, width)
}

func (a *app) readPreviewDir(path string) ([]string, error) {
	dirEntries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(dirEntries))
	for _, de := range dirEntries {
		name := de.Name()
		if a.cfg.hideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if a.cfg.dirOnly && !de.IsDir() {
			continue
		}
		if de.IsDir() {
			name += "/"
		}
		names = append(names, name)
	}
	sort.Strings(names)
	return names, nil
}

func (a *app) readPreviewFile(path string, limit, width int) []string {
	file, err := os.Open(path)
	if err != nil {
		return popupLines(err.Error(), limit)
	}
	defer file.Close()

	reader := bufio.NewReader(io.LimitReader(file, 64*1024))
	data, _ := io.ReadAll(reader)
	if bytesContainNUL(data) || !utf8.Valid(data) {
		return nil
	}
	text := strings.ReplaceAll(string(data), "\r\n", "\n")
	rawLines := strings.Split(text, "\n")
	lines := make([]string, 0, limit)
	for _, line := range rawLines {
		if len(lines) >= limit {
			break
		}
		lines = append(lines, truncatePad(line, width))
	}
	return lines
}

func bytesContainNUL(data []byte) bool {
	for _, b := range data {
		if b == 0 {
			return true
		}
	}
	return false
}

func (a *app) renderList(limit, width int) []string {
	end := a.scroll + limit
	if end > len(a.entries) {
		end = len(a.entries)
	}
	if end < a.scroll {
		end = a.scroll
	}

	displayWidth := width
	if displayWidth <= 0 {
		for _, item := range a.entries {
			w := runewidth.StringWidth(item.displayName(a.cfg.icons, a.icons))
			if w > displayWidth {
				displayWidth = w
			}
		}
	}
	if displayWidth <= 0 {
		displayWidth = 1
	}

	lines := make([]string, 0, end-a.scroll)
	for idx := a.scroll; idx < end; idx++ {
		item := a.entries[idx]
		line := truncatePad(item.displayName(a.cfg.icons, a.icons), displayWidth)
		if idx == a.armedDelete {
			line = selectionColor(line, deleteColor)
		} else if idx == a.selected {
			line = selectionColor(line, a.mainColor)
		}
		lines = append(lines, line)
	}
	return lines
}

func (a *app) headerText() string {
	if a.topMessage != "" {
		return a.topMessage
	}
	return a.currentPath
}

func (a *app) searchSuffix() string {
	if !a.searchMode {
		return ""
	}
	return "/" + a.searchQuery
}

func (a *app) headerLine(left, right string, width int) string {
	leftWidth := width
	if right != "" {
		leftWidth = width - runewidth.StringWidth(right)
		if leftWidth < 0 {
			leftWidth = 0
		}
	}
	leftStyled := styleBar(truncatePad(left, leftWidth))
	if right == "" {
		return leftStyled
	}
	return leftStyled + styleQuery(right)
}

func styleBar(value string) string {
	return fmt.Sprintf("\x1b[38;5;%d;48;5;%dm%s\x1b[0m", foregroundColor, headerColor, value)
}

func styleQuery(value string) string {
	return fmt.Sprintf("\x1b[38;5;%d;48;5;%dm%s\x1b[0m", foregroundColor, queryColor, value)
}

func selectionColor(value string, color int) string {
	if color < 0 {
		return fmt.Sprintf("\x1b[38;5;%dm%s\x1b[0m", foregroundColor, value)
	}
	return fmt.Sprintf("\x1b[38;5;%d;48;5;%dm%s\x1b[0m", foregroundColor, color, value)
}

func fgColor(value string, color int) string {
	if color < 0 {
		return value
	}
	return fmt.Sprintf("\x1b[38;5;%dm%s\x1b[0m", color, value)
}

func popupLines(message string, limit int) []string {
	if limit <= 0 {
		return nil
	}
	boxWidth := runewidth.StringWidth(message) + 2
	top := "+" + strings.Repeat("-", boxWidth) + "+"
	mid := "| " + message + " |"
	bot := "+" + strings.Repeat("-", boxWidth) + "+"
	lines := []string{top, mid, bot}
	if len(lines) > limit {
		return lines[:limit]
	}
	return lines
}

func truncatePad(value string, width int) string {
	if width <= 0 {
		return ""
	}
	value = runewidth.Truncate(value, width, "")
	return padRight(value, width)
}

func padRight(value string, width int) string {
	gap := width - runewidth.StringWidth(value)
	if gap <= 0 {
		return value
	}
	return value + strings.Repeat(" ", gap)
}

func padAll(lines []string, width int) []string {
	if width <= 0 {
		return lines
	}
	result := make([]string, 0, len(lines))
	for _, line := range lines {
		result = append(result, truncatePad(line, width))
	}
	return result
}

func (a *app) footerLine() string {
	if a.pending != nil {
		seconds := int(math.Ceil(time.Until(a.pending.deadline).Seconds()))
		if seconds < 0 {
			seconds = 0
		}
		return fmt.Sprintf("%s deleted. (u)ndo %d", a.pending.name, seconds)
	}
	if a.status == nil || a.currentEntry() == nil {
		return ""
	}
	return a.status.evaluate(a.currentEntry(), a.entries)
}

func (a *app) listRowsAvailable() int {
	rows := a.rows - 1
	if a.pending != nil || (a.status != nil && a.currentEntry() != nil && !a.showHelp) {
		rows--
	}
	if a.preview {
		rows = a.rows - 1
		if a.pending != nil || (a.status != nil && a.currentEntry() != nil) {
			rows--
		}
	}
	if rows < 0 {
		return 0
	}
	return rows
}

