	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/vm"
	"github.com/mattn/go-runewidth"
)

type statusProgram struct {
	program *vm.Program
}

func compileStatusProgram(source string) *statusProgram {
	source = strings.TrimSpace(source)
	if source == "" {
		return nil
	}
	program, err := expr.Compile(source, expr.Env(statusEnvPrototype()))
	if err != nil {
		panic(err)
	}
	return &statusProgram{program: program}
}

func statusEnvPrototype() map[string]any {
	return map[string]any{
		"current_file": (fs.DirEntry)(nil),
		"files":        []fs.DirEntry{},
		"Sprintf": func(format string, args ...any) string {
			return ""
		},
		"PadLeft": func(value any, width int) string {
			return ""
		},
		"PadRight": func(value any, width int) string {
			return ""
		},
		"Size": func() string {
			return ""
		},
		"Mode": func() string {
			return ""
		},
		"ModTime": func() string {
			return ""
		},
		"Owner": func() string {
			return ""
		},
	}
}

func (p *statusProgram) evaluate(current *entry, entries []entry) string {
	files := make([]fs.DirEntry, 0, len(entries))
	for _, item := range entries {
		files = append(files, item.dirEntry)
	}

	env := map[string]any{
		"current_file": current.dirEntry,
		"files":        files,
		"Sprintf": func(format string, args ...any) string {
			return fmt.Sprintf(format, args...)
		},
		"PadLeft": func(value any, width int) string {
			return padLeft(fmt.Sprint(value), width)
		},
		"PadRight": func(value any, width int) string {
			return padRight(fmt.Sprint(value), width)
		},
		"Size": func() string {
			info, err := current.dirEntry.Info()
			if err != nil {
				return ""
			}
			return humanSize(info.Size())
		},
		"Mode": func() string {
			info, err := current.dirEntry.Info()
			if err != nil {
				return ""
			}
			return info.Mode().String()
		},
		"ModTime": func() string {
			info, err := current.dirEntry.Info()
			if err != nil {
				return ""
			}
			return info.ModTime().Format("Jan _2 15:04")
		},
		"Owner": func() string {
			info, err := current.dirEntry.Info()
			if err != nil {
				return ""
			}
			return ownerString(info)
		},
	}

	result, err := expr.Run(p.program, env)
	if err != nil {
		return ""
	}
	return fmt.Sprint(result)
}

func padLeft(value string, width int) string {
	gap := width - runewidth.StringWidth(value)
	if gap <= 0 {
		return value
	}
	return strings.Repeat(" ", gap) + value
}

func humanSize(size int64) string {
	if size < 1024 {
		return fmt.Sprintf("%dB", size)
	}
	units := []string{"K", "M", "G", "T", "P"}
	value := float64(size)
	unit := "B"
	for _, next := range units {
		value /= 1024
		unit = next
		if value < 1024 {
			break
		}
	}
	if value >= 10 {
		return fmt.Sprintf("%.0f%s", value, unit)
	}
	return fmt.Sprintf("%.1f%s", value, unit)
}

func ownerString(info os.FileInfo) string {
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok {
		return ""
	}
	return lookupUser(stat.Uid) + " " + lookupGroup(stat.Gid)
}

func lookupUser(uid uint32) string {
	value := strconv.FormatUint(uint64(uid), 10)
	found, err := user.LookupId(value)
	if err != nil {
		return value
	}
	return found.Username
}

func lookupGroup(gid uint32) string {
	value := strconv.FormatUint(uint64(gid), 10)
	found, err := user.LookupGroupId(value)
	if err != nil {
		return value
	}
	return found.Name
}

var _ = time.Second

