package main

import (
	"embed"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

//go:embed etc/icons
var iconFS embed.FS

type iconRule struct {
	pattern string
	icon    string
	lower   bool
}

type iconMatcher struct {
	typeIcons map[string]string
	rules     []iconRule
}

func mustLoadIconMatcher() *iconMatcher {
	data, err := fs.ReadFile(iconFS, "etc/icons")
	if err != nil {
		return nil
	}
	matcher := &iconMatcher{
		typeIcons: map[string]string{},
	}
	for _, line := range strings.Split(string(data), "\n") {
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = line[:idx]
		}
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		key := strings.Trim(fields[0], "'")
		icon := fields[1]
		if isTypeKey(key) {
			matcher.typeIcons[key] = icon
			continue
		}
		matcher.rules = append(matcher.rules, iconRule{
			pattern: key,
			icon:    icon,
			lower:   key == strings.ToLower(key),
		})
	}
	return matcher
}

func isTypeKey(key string) bool {
	switch key {
	case "ln", "or", "tw", "ow", "st", "di", "pi", "so", "bd", "cd", "su", "sg", "ex", "fi":
		return true
	default:
		return false
	}
}

func (m *iconMatcher) iconFor(de os.DirEntry, path string) string {
	if m == nil || de == nil {
		return ""
	}
	name := de.Name()
	lower := strings.ToLower(name)
	matched := ""
	for _, rule := range m.rules {
		candidate := name
		if rule.lower {
			candidate = lower
		}
		ok, err := filepath.Match(rule.pattern, candidate)
		if err == nil && ok {
			matched = rule.icon
		}
	}
	if matched != "" {
		return matched
	}
	return m.typeIcons[fileTypeKey(de, path)]
}

func fileTypeKey(de os.DirEntry, path string) string {
	info, err := de.Info()
	if err != nil {
		return "fi"
	}
