package main

import (
	"syscall"
	"unsafe"
)

type terminalState struct {
	termios syscall.Termios
}

type winsize struct {
	rows uint16
	cols uint16
	x    uint16
	y    uint16
}

func makeRaw(fd int) (*terminalState, error) {
	var old syscall.Termios
	if err := ioctl(fd, syscall.TCGETS, uintptr(unsafe.Pointer(&old))); err != nil {
		return nil, err
	}
	newState := old
	newState.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	newState.Oflag &^= syscall.OPOST
	newState.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	newState.Cflag &^= syscall.CSIZE | syscall.PARENB
	newState.Cflag |= syscall.CS8
	newState.Cc[syscall.VMIN] = 1
	newState.Cc[syscall.VTIME] = 0
	if err := ioctl(fd, syscall.TCSETS, uintptr(unsafe.Pointer(&newState))); err != nil {
		return nil, err
	}
	return &terminalState{termios: old}, nil
}

func restoreTerminal(fd int, state *terminalState) error {
	if state == nil {
		return nil
	}
	return ioctl(fd, syscall.TCSETS, uintptr(unsafe.Pointer(&state.termios)))
}

func getTerminalSize(fd int) (int, int, error) {
	var ws winsize
	if err := ioctl(fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws))); err != nil {
		return 0, 0, err
	}
	return int(ws.cols), int(ws.rows), nil
}

func availableToRead(fd int) (int, error) {
	var value int32
	if err := ioctl(fd, syscall.FIONREAD, uintptr(unsafe.Pointer(&value))); err != nil {
		return 0, err
	}
	return int(value), nil
}

func ioctl(fd int, req uintptr, arg uintptr) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), req, arg)
	if errno != 0 {
		return errno
	}
	return nil
}

