package main

import (
	"fmt"
	"io/fs"
	"os"
	"os/user"
	"strconv"
	"strings"
	"syscall"
	"time"
)

type statusProgram struct {
	root statusExpr
}

func compileStatusProgram(source string) *statusProgram {
	source = strings.TrimSpace(source)
	if source == "" {
		return nil
	}
	tokens, err := tokenizeStatus(source)
	if err != nil {
		panic(err)
	}
	parser := &statusParser{tokens: tokens}
	root, err := parser.parse()
	if err != nil {
		panic(err)
	}
	return &statusProgram{root: root}
}

func (p *statusProgram) evaluate(current *entry, entries []entry) string {
	if p == nil || p.root == nil {
		return ""
	}
	ctx := statusContext{
		current: current,
		entries: entries,
	}
	value, err := p.root.eval(ctx)
	if err != nil {
		return ""
	}
	return fmt.Sprint(value)
}

type statusContext struct {
	current *entry
	entries []entry
}

type statusExpr interface {
	eval(statusContext) (any, error)
}

type literalExpr struct {
	value any
}

func (e literalExpr) eval(_ statusContext) (any, error) {
	return e.value, nil
}

type identExpr struct {
	name string
}

func (e identExpr) eval(ctx statusContext) (any, error) {
	switch e.name {
	case "current_file":
		if ctx.current == nil {
			return nil, nil
		}
		return ctx.current.dirEntry, nil
	case "files":
		files := make([]fs.DirEntry, 0, len(ctx.entries))
		for _, item := range ctx.entries {
			files = append(files, item.dirEntry)
		}
		return files, nil
	default:
		return e.name, nil
	}
}

type listExpr struct {
	items []statusExpr
}

func (e listExpr) eval(ctx statusContext) (any, error) {
	result := make([]any, 0, len(e.items))
	for _, item := range e.items {
		value, err := item.eval(ctx)
		if err != nil {
			return nil, err
		}
		result = append(result, value)
	}
	return result, nil
}

type callExpr struct {
	name string
	args []statusExpr
}

func (e callExpr) eval(ctx statusContext) (any, error) {
	args := make([]any, 0, len(e.args))
	for _, argExpr := range e.args {
		value, err := argExpr.eval(ctx)
		if err != nil {
			return nil, err
		}
		args = append(args, value)
	}
	return callStatusFunction(ctx, e.name, args)
}

type selectorExpr struct {
	target statusExpr
	name   string
	args   []statusExpr
	call   bool
}

func (e selectorExpr) eval(ctx statusContext) (any, error) {
	target, err := e.target.eval(ctx)
	if err != nil {
		return nil, err
	}
	args := make([]any, 0, len(e.args))
	for _, argExpr := range e.args {
		value, argErr := argExpr.eval(ctx)
		if argErr != nil {
			return nil, argErr
		}
		args = append(args, value)
	}
	return evalSelector(target, e.name, e.call, args)
}

type pipeExpr struct {
	left  statusExpr
	right callExpr
}

func (e pipeExpr) eval(ctx statusContext) (any, error) {
	left, err := e.left.eval(ctx)
	if err != nil {
		return nil, err
	}
	args := make([]statusExpr, 0, len(e.right.args)+1)
	args = append(args, literalExpr{value: left})
	args = append(args, e.right.args...)
	return callExpr{name: e.right.name, args: args}.eval(ctx)
}

func callStatusFunction(ctx statusContext, name string, args []any) (any, error) {
	switch name {
	case "Sprintf":
		if len(args) == 0 {
			return "", nil
		}
		format, _ := args[0].(string)
		return fmt.Sprintf(format, args[1:]...), nil
	case "PadLeft":
		if len(args) != 2 {
			return "", nil
		}
		return padLeft(fmt.Sprint(args[0]), toInt(args[1])), nil
	case "PadRight":
		if len(args) != 2 {
			return "", nil
		}
		return padRight(fmt.Sprint(args[0]), toInt(args[1])), nil
	case "Size":
		if ctx.current == nil {
			return "", nil
		}
		info, err := ctx.current.dirEntry.Info()
		if err != nil {
			return "", nil
		}
		return humanSize(info.Size()), nil
	case "Mode":
		if ctx.current == nil {
			return "", nil
		}
		info, err := ctx.current.dirEntry.Info()
		if err != nil {
			return "", nil
		}
		return info.Mode().String(), nil
	case "ModTime":
		if ctx.current == nil {
			return "", nil
		}
		info, err := ctx.current.dirEntry.Info()
		if err != nil {
			return "", nil
		}
		return info.ModTime().Format("Jan _2 15:04"), nil
	case "Owner":
		if ctx.current == nil {
			return "", nil
		}
		info, err := ctx.current.dirEntry.Info()
		if err != nil {
			return "", nil
		}
		return ownerString(info), nil
	case "join":
		if len(args) != 2 {
			return "", nil
		}
		parts, ok := args[0].([]any)
		if !ok {
			return "", nil
		}
		values := make([]string, 0, len(parts))
		for _, part := range parts {
			values = append(values, fmt.Sprint(part))
		}
		return strings.Join(values, fmt.Sprint(args[1])), nil
	case "len":
		if len(args) != 1 {
			return 0, nil
		}
		switch value := args[0].(type) {
		case string:
			return len([]rune(value)), nil
		case []any:
			return len(value), nil
		case []fs.DirEntry:
			return len(value), nil
		default:
			return 0, nil
		}
	default:
		return "", nil
	}
}

func evalSelector(target any, name string, call bool, args []any) (any, error) {
	switch value := target.(type) {
	case fs.DirEntry:
		switch name {
		case "Name":
			if call {
				return value.Name(), nil
			}
		case "IsDir":
			if call {
				return value.IsDir(), nil
			}
		case "Type":
			if call {
				return value.Type(), nil
			}
		case "Info":
			if call {
				return value.Info()
			}
		}
	case os.FileInfo:
		switch name {
		case "Name":
			if call {
				return value.Name(), nil
			}
		case "Size":
			if call {
				return value.Size(), nil
			}
		case "Mode":
			if call {
				return value.Mode(), nil
			}
		case "ModTime":
			if call {
				return value.ModTime(), nil
			}
		case "IsDir":
			if call {
				return value.IsDir(), nil
			}
		}
	case fs.FileMode:
		switch name {
		case "String":
			if call {
				return value.String(), nil
			}
		}
	case time.Time:
		switch name {
		case "Format":
			if call && len(args) == 1 {
				return value.Format(fmt.Sprint(args[0])), nil
			}
		}
	}
	return "", nil
}

func padLeft(value string, width int) string {
	gap := width - stringWidth(value)
	if gap <= 0 {
		return value
	}
	return strings.Repeat(" ", gap) + value
}

func humanSize(size int64) string {
	if size < 1024 {
		return fmt.Sprintf("%dB", size)
	}
	units := []string{"K", "M", "G", "T", "P"}
	value := float64(size)
	unit := "B"
	for _, next := range units {
		value /= 1024
		unit = next
		if value < 1024 {
			break
		}
	}
	if value >= 10 {
		return fmt.Sprintf("%.0f%s", value, unit)
	}
	return fmt.Sprintf("%.1f%s", value, unit)
}

func ownerString(info os.FileInfo) string {
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok {
		return ""
	}
	return lookupUser(stat.Uid) + " " + lookupGroup(stat.Gid)
}

func lookupUser(uid uint32) string {
	value := strconv.FormatUint(uint64(uid), 10)
	found, err := user.LookupId(value)
	if err != nil {
		return value
	}
	return found.Username
}

func lookupGroup(gid uint32) string {
	value := strconv.FormatUint(uint64(gid), 10)
	found, err := user.LookupGroupId(value)
	if err != nil {
		return value
	}
	return found.Name
}

func toInt(value any) int {
	switch v := value.(type) {
	case int:
		return v
	case int64:
		return int(v)
	case uint64:
		return int(v)
	case string:
		n, _ := strconv.Atoi(v)
		return n
	default:
		return 0
	}
}

type statusTokenKind int

const (
	tokenEOF statusTokenKind = iota
	tokenIdent
	tokenString
	tokenInt
	tokenLParen
	tokenRParen
	tokenLBracket
	tokenRBracket
	tokenComma
	tokenPipe
	tokenDot
)

type statusToken struct {
	kind  statusTokenKind
	value string
}

func tokenizeStatus(source string) ([]statusToken, error) {
	var tokens []statusToken
	for len(source) > 0 {
		switch {
		case source[0] == ' ' || source[0] == '\n' || source[0] == '\t' || source[0] == '\r':
			source = source[1:]
		case isStatusIdentStart(source[0]):
			i := 1
			for i < len(source) && isStatusIdentPart(source[i]) {
				i++
			}
			tokens = append(tokens, statusToken{kind: tokenIdent, value: source[:i]})
			source = source[i:]
		case source[0] >= '0' && source[0] <= '9':
			i := 1
			for i < len(source) && source[i] >= '0' && source[i] <= '9' {
				i++
			}
			tokens = append(tokens, statusToken{kind: tokenInt, value: source[:i]})
			source = source[i:]
		case source[0] == '"':
			i := 1
			for i < len(source) {
				if source[i] == '\\' {
					i += 2
					continue
				}
				if source[i] == '"' {
					i++
					break
				}
				i++
			}
			if i > len(source) || source[i-1] != '"' {
				return nil, fmt.Errorf("unterminated string")
			}
			value, err := strconv.Unquote(source[:i])
			if err != nil {
